-- main.sql: base de datos completa de la Tarea 2 individual (Ruteo Resiliente en Redes).
-- Generado por main.py el 2026-11-19 20:16 en PostgreSQL 16.9 (Debian 16.9-1.pgdg110+1) + PostGIS 3.5.2 + pgRouting 3.7.3.
--
-- Contiene: infraestructura (fibra_raw), topologia (fibra_red con source/target/p_falla y fibra_red_vertices_pgr),
-- nodos clave (nodos_clave, nodo_red), sismo (sismo), modelo y probabilidades de falla (youngs1997_coef,
-- parametros_falla, funcion youngs1997, columna fibra_red.p_falla, vista falla_tramo) y los ATTR (attr_resultado).
-- Sismo: USGS official20100227063411530_30, Mw 8.8, epicentro lon -72.898 lat -36.122, profundidad 22.9 km.
-- Modelo: Youngs et al. (1997) interfaz, sitio 'soil' -> Sa(1,0) -> PGV (Newmark y Hall 1982) -> RR = K*0,00187*PGV
--   (ALA 2001), K = 1.0 -> P = 1 - exp(-suma RR*largo), sub-tramos de <= 2.0 km, distancia con ST_Distance(geography).
--
-- Se carga en una base VACIA con (desde la carpeta del repositorio, con la base levantada):
--   docker exec tarea2_resiliencia_db createdb -U tarea2 vacia
--   docker cp sql/main.sql tarea2_resiliencia_db:/tmp/main.sql
--   docker exec tarea2_resiliencia_db psql -U tarea2 -d vacia -v ON_ERROR_STOP=1 -q -f /tmp/main.sql
-- o con: python main.py todo --desde-main-sql   (si la base ya tiene estas tablas, se borran y se vuelven a crear).

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET client_min_messages = warning;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgrouting;

BEGIN;
DROP VIEW IF EXISTS falla_tramo;
DROP TABLE IF EXISTS attr_resultado CASCADE;
DROP TABLE IF EXISTS nodo_red CASCADE;
DROP TABLE IF EXISTS nodos_clave CASCADE;
DROP TABLE IF EXISTS sismo CASCADE;
DROP TABLE IF EXISTS fibra_red_vertices_pgr CASCADE;
DROP TABLE IF EXISTS fibra_red CASCADE;
DROP TABLE IF EXISTS fibra_raw CASCADE;
DROP TABLE IF EXISTS parametros_falla CASCADE;
DROP TABLE IF EXISTS youngs1997_coef CASCADE;

-- ===== youngs1997_coef: Coeficientes de Youngs et al. (1997), tabla 2, interfaz de subduccion (4 filas)
CREATE TABLE youngs1997_coef (
    sitio text NOT NULL,
    medida text NOT NULL,
    a1 double precision NOT NULL,
    a2 double precision NOT NULL,
    a3 double precision NOT NULL,
    a4 double precision NOT NULL,
    a5 double precision NOT NULL,
    a6 double precision NOT NULL,
    c1 double precision NOT NULL,
    c2 double precision NOT NULL,
    c3 double precision NOT NULL,
    CONSTRAINT youngs1997_coef_pkey PRIMARY KEY (sitio, medida),
    CONSTRAINT youngs1997_coef_medida_check CHECK ((medida = ANY (ARRAY['pga'::text, 'sa1'::text]))),
    CONSTRAINT youngs1997_coef_sitio_check CHECK ((sitio = ANY (ARRAY['rock'::text, 'soil'::text])))
);
COMMENT ON TABLE youngs1997_coef IS 'Coeficientes de Youngs et al. (1997), tabla 2, interfaz de subduccion';

-- ===== parametros_falla: Parametros del modelo de falla (sitio, K de ALA 2001, largo de sub-tramo, conversiones) (1 filas)
CREATE TABLE parametros_falla (
    id integer DEFAULT 1 NOT NULL,
    sitio text DEFAULT 'soil'::text NOT NULL,
    k_ala double precision DEFAULT 1.0 NOT NULL,
    paso_max_km double precision DEFAULT 2.0 NOT NULL,
    pgv_por_g double precision DEFAULT (((386.09)::double precision / (((2)::double precision * pi()) * (1.65)::double precision)) * (2.54)::double precision) NOT NULL,
    rr_por_cm_s_km double precision DEFAULT ((0.00187 * ((1000)::numeric / 304.8)) / 2.54) NOT NULL,
    CONSTRAINT parametros_falla_pkey PRIMARY KEY (id),
    CONSTRAINT parametros_falla_id_check CHECK ((id = 1)),
    CONSTRAINT parametros_falla_sitio_check CHECK ((sitio = ANY (ARRAY['rock'::text, 'soil'::text])))
);
COMMENT ON TABLE parametros_falla IS 'Parametros del modelo de falla (sitio, K de ALA 2001, largo de sub-tramo, conversiones)';

-- ===== fibra_raw: Infraestructura: polilineas de fibra optica detectada (proyecto Yafun, shapefile oficial de Subtel) (1,915 filas)
CREATE TABLE fibra_raw (
    gid integer NOT NULL,
    feature_id text,
    parte integer DEFAULT 1 NOT NULL,
    fuente text NOT NULL,
    geom geometry(LineString,4326) NOT NULL,
    CONSTRAINT fibra_raw_pkey PRIMARY KEY (gid)
);
COMMENT ON TABLE fibra_raw IS 'Infraestructura: polilineas de fibra optica detectada (proyecto Yafun, shapefile oficial de Subtel)';

-- ===== fibra_red: Topologia: aristas (tramos entre vertices consecutivos) con source/target de pgr_createTopology y p_falla (22,705 filas)
CREATE TABLE fibra_red (
    id integer NOT NULL,
    linea_id integer,
    tramo_id bigint,
    orden integer,
    geom geometry(LineString,4326),
    largo_m double precision,
    source integer,
    target integer,
    bucle boolean,
    p_falla double precision DEFAULT 0 NOT NULL,
    dist_epicentro_m double precision,
    dist_hipocentral_km double precision,
    pga_g double precision,
    pgv_cm_s double precision,
    cortes_esperados double precision,
    CONSTRAINT fibra_red_pkey PRIMARY KEY (id),
    CONSTRAINT fibra_red_p_falla_check CHECK (((p_falla >= (0)::double precision) AND (p_falla <= (1)::double precision)))
);
COMMENT ON TABLE fibra_red IS 'Topologia: aristas (tramos entre vertices consecutivos) con source/target de pgr_createTopology y p_falla';
COMMENT ON COLUMN fibra_red.p_falla IS 'Probabilidad de falla del enlace por el sismo (0 por defecto = en operacion)';
COMMENT ON COLUMN fibra_red.dist_epicentro_m IS 'Distancia geodesica (ST_Distance sobre geography, metros) del punto medio de la arista al epicentro';
COMMENT ON COLUMN fibra_red.dist_hipocentral_km IS 'Distancia hipocentral del punto medio: sqrt(d_epicentro^2 + H^2), km';
COMMENT ON COLUMN fibra_red.pga_g IS 'PGA mediana en el punto medio (Youngs et al. 1997), g';
COMMENT ON COLUMN fibra_red.pgv_cm_s IS 'PGV mediana en el punto medio (Newmark y Hall 1982), cm/s';
COMMENT ON COLUMN fibra_red.cortes_esperados IS 'Cortes esperados en la arista: suma de RR*largo de sus sub-tramos (ALA 2001)';

-- ===== fibra_red_vertices_pgr: Topologia: tabla de vertices creada por pgr_createTopology (cnt/chk/ein/eout de pgr_analyzeGraph) (22,673 filas)
CREATE TABLE fibra_red_vertices_pgr (
    id bigint NOT NULL,
    cnt integer,
    chk integer,
    ein integer,
    eout integer,
    the_geom geometry(Point,4326),
    CONSTRAINT fibra_red_vertices_pgr_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE fibra_red_vertices_pgr IS 'Topologia: tabla de vertices creada por pgr_createTopology (cnt/chk/ein/eout de pgr_analyzeGraph)';

-- ===== sismo: Sismo Mw 8,8 del 27-02-2010 (GeoJSON del USGS) (1 filas)
CREATE TABLE sismo (
    id text NOT NULL,
    magnitud double precision NOT NULL,
    tipo_magnitud text,
    lugar text,
    fecha_utc timestamp with time zone,
    profundidad_km double precision,
    geom geometry(Point,4326) NOT NULL,
    propiedades jsonb,
    CONSTRAINT sismo_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE sismo IS 'Sismo Mw 8,8 del 27-02-2010 (GeoJSON del USGS)';

-- ===== nodos_clave: Nodos clave: generan (centros de datos), intercambian (IXP, amarres de cables), reciben (comunas) (399 filas)
CREATE TABLE nodos_clave (
    id integer NOT NULL,
    nombre text NOT NULL,
    rol text NOT NULL,
    tipo text NOT NULL,
    fuente text NOT NULL,
    cut_com text,
    geom geometry(Point,4326) NOT NULL,
    CONSTRAINT nodos_clave_pkey PRIMARY KEY (id),
    CONSTRAINT nodos_clave_rol_check CHECK ((rol = ANY (ARRAY['genera'::text, 'intercambia'::text, 'recibe'::text])))
);
COMMENT ON TABLE nodos_clave IS 'Nodos clave: generan (centros de datos), intercambian (IXP, amarres de cables), reciben (comunas)';

-- ===== nodo_red: Union de cada nodo clave con un vertice de la topologia (399 filas)
CREATE TABLE nodo_red (
    nodo_id integer NOT NULL,
    vertice_id integer,
    dist_m double precision,
    conectado boolean NOT NULL,
    CONSTRAINT nodo_red_pkey PRIMARY KEY (nodo_id),
    CONSTRAINT nodo_red_nodo_id_fkey FOREIGN KEY (nodo_id) REFERENCES nodos_clave(id) ON DELETE CASCADE
);
COMMENT ON TABLE nodo_red IS 'Union de cada nodo clave con un vertice de la topologia';

-- ===== attr_resultado: ATTR en operacion y despues del sismo (salida de main.py) (44 filas)
CREATE TABLE attr_resultado (
    escenario text NOT NULL,
    metrica text NOT NULL,
    valor double precision,
    CONSTRAINT attr_resultado_pkey PRIMARY KEY (escenario, metrica)
);
COMMENT ON TABLE attr_resultado IS 'ATTR en operacion y despues del sismo (salida de main.py)';

-- ===== indices
CREATE INDEX fibra_raw_geom_gix ON public.fibra_raw USING gist (geom);
CREATE INDEX fibra_red_geom_gix ON public.fibra_red USING gist (geom);
CREATE INDEX fibra_red_source_idx ON public.fibra_red USING btree (source);
CREATE INDEX fibra_red_source_ix ON public.fibra_red USING btree (source);
CREATE INDEX fibra_red_target_idx ON public.fibra_red USING btree (target);
CREATE INDEX fibra_red_target_ix ON public.fibra_red USING btree (target);
CREATE INDEX fibra_red_vertices_pgr_the_geom_idx ON public.fibra_red_vertices_pgr USING gist (the_geom);
CREATE INDEX sismo_geom_gix ON public.sismo USING gist (geom);
CREATE INDEX nodos_clave_geom_gix ON public.nodos_clave USING gist (geom);

-- ===== funcion del modelo de falla (Youngs et al. 1997)
CREATE OR REPLACE FUNCTION public.youngs1997(r_km double precision, mag double precision, h_km double precision, p_sitio text, p_medida text)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
    SELECT exp(c.a1 + c.a2 * mag + c.c1 + c.c2 * power(c.a3 - mag, 3)
               + c.c3 * ln(r_km + c.a4 * exp(c.a5 * mag)) + c.a6 * h_km)
    FROM youngs1997_coef c
    WHERE c.sitio = p_sitio AND c.medida = p_medida
$function$;

-- ===== vista falla_tramo
CREATE VIEW falla_tramo AS
 SELECT tramo_id,
    count(*) AS aristas,
    sum(largo_m) / 1000::double precision AS largo_km,
    sum(cortes_esperados) AS cortes_esperados,
    1::double precision - exp(- sum(cortes_esperados)) AS p_falla,
    avg(pga_g) AS pga_g,
    avg(pgv_cm_s) AS pgv_cm_s,
    avg(dist_hipocentral_km) AS dist_hipocentral_km,
    st_linemerge(st_collect(geom ORDER BY orden)) AS geom
   FROM fibra_red
  GROUP BY tramo_id;

COMMIT;
ANALYZE;
